def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return "PATH\n1\n1\n"

    # Parse input
    parts = lines[0].split()
    n, m, k = int(parts[0]), int(parts[1]), int(parts[2])

    edges = []
    adj = defaultdict(list)

    for i in range(1, len(lines)):
        v, u = map(int, lines[i].split())
        adj[v].append(u)
        adj[u].append(v)
        edges.append((v, u))

    # Try to find a path of length >= n/k
    target_len = (n + k - 1) // k  # ceiling division

    # DFS to find long paths
    def dfs_path(start):
        visited = [False] * (n + 1)
        path = []

        def search(node):
            visited[node] = True
            path.append(node)
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    if len(path) >= target_len:
                        return path
                    search(neighbor)
                    if visited[neighbor]:
                        pass  # Continue searching
                path.pop()
            if visited[node] and not any(visited[p] for p in path if p != node):
                return path
            return None

        return search(start)

    # Find a path
    path = None
    for node in range(1, n + 1):
        path = dfs_path(node)
        if path is not None:
            break

    if path and len(path) >= target_len:
        path_str = " ".join(map(str, path))
        return f"PATH\n{len(path)}\n{path_str}\n"

    # Try to find k cycles
    # Find cycles with length not divisible by 3
    def find_cycles():
        cycles = []
        visited = [False] * (n + 1)

        # Each block of 3 nodes forms a potential cycle structure
        for node in range(1, n + 1):
            if not visited[node]:
                # DFS to find cycles
                stack = [(node, [node])]
                while stack:
                    curr, path = stack.pop()
                    for neighbor in adj[curr]:
                        if not visited[neighbor]:
                            stack.append((neighbor, path + [neighbor]))
                        elif neighbor in path:
                            cycle = path[path.index(neighbor):] + [neighbor]
                            if len(cycle) >= 3 and len(cycle) % 3 != 0:
                                cycles.append(cycle)
                visited[node] = True

        return cycles[:k]  # Return up to k cycles

    cycles = find_cycles()
    if len(cycles) >= k:
        result = ["CYCLES"]
        for cycle in cycles[:k]:
            result.append(str(len(cycle)))
            result.append(" " + " ".join(map(str, cycle)))
        return "\n".join(result) + "\n"

    return "PATH\n1\n1\n"
