```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    adj = [[] for _ in range(n + 1)]

    for line in lines[1:]:
        if line.strip():
            a, b = map(int, line.split())
            adj[a].append(b)
            adj[b].append(a)

    def bfs(start):
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = [start]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist

    all_dists = [bfs(i) for i in range(1, n + 1)]

    def is_derangement(p):
        for i in range(n):
            if p[i] == i + 1:
                return False
        return True

    def score(p):
        total = 0
        for i in range(n):
            total += all_dists[i + 1][p[i]]
        return total

    best_p = None
    best_score = -1

    # Try various rotation patterns
    for shift in range(1, n):
        p = []
        for j in range(n):
            target = (j + shift) % n
            p.append(target + 1)
        if is_derangement(p):
            s = score(p)
            if s > best_score:
                best_score = s
                best_p = p

    # Try reversal
    if n < 100000:
        rev = list(range(n, 0, -1))
        if is_derangement(rev):
            s = score(rev)
            if s > best_score:
                best_score = s
                best_p = rev

    return f"{best_score}\n{' '.join(map(str, best_p))}"
