    # Check if any lucky number can be formed by summing components
    # Using DP: dp[s] = minimum number of components needed to form sum s
    dp = {0: 0}
    for s in components:
        new_dp = dict(dp)
        for prev_sum, count in dp.items():
            new_sum = prev_sum + s
            new_count = count + 1
            if new_sum not in new_dp or new_count < new_dp[new_sum]:
                new_dp[new_sum] = new_count
        dp = new_dp

    # Find minimum roads needed (components - 1)
    answer = -1
    for lucky in lucky_numbers:
        if lucky in dp and dp[lucky] >= 1:
            roads = dp[lucky] - 1
            if answer == -1 or roads < answer:
                answer = roads

    return f"{answer}\n"
