def solution(input_str):
    """
    Find the k-th correct 2D bracket array based on priority ordering.
    """
    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    priorities = [list(map(int, row.split())) for row in lines[1:]]

    # Sort positions by priority (lower priority = earlier position)
    pos_list = [(priorities[i][j], i, j) for i in range(n) for j in range(m)]
    pos_list.sort(key=lambda x: x[0])

    valid_arrays = []

    def check_all_paths(grid):
        # Verify every monotonic path forms valid bracket sequence
        def valid_from(i, j, bal):
            if bal < 0:
                return False
            if i == n and j == m:
                return bal == 0
            if j < m and grid[i][j] == '(':
                if valid_from(i, j + 1, bal + 1):
                    return True
            if j < m and grid[i][j] == ')':
                if valid_from(i, j + 1, bal - 1):
                    return True
            if i < n:
                if valid_from(i + 1, j, bal):
                    return True
            return False

        return valid_from(1, 1, 0)

    grid = [[''] * m for _ in range(n)]

    def generate(idx):
        if idx == n * m:
            if check_all_paths([row[:] for row in grid]):
                valid_arrays.append(tuple(tuple(row) for row in grid))
            return

        i, j = idx // m, idx % m
        for ch in ['(', ')']:
            grid[i][j] = ch
            generate(idx + 1)
            grid[i][j] = ''

    generate(0)

    # Sort by priority order: lower priority position with '(' comes before ')'
    def sort_key(arr):
        return tuple(arr[i][j] for i in range(n) for j in range(m))

    valid_arrays.sort(key=sort_key)

    return '\n'.join(''.join(arr[i][j] for j in range(m)) for i in range(n))
