def solution(input_str):
    """
    Solve the competitive programming problem by counting triples (A, B, C)
    where the digital root condition passes but AB != C.

    For N up to 10^6, we use O(n) for counting divisors.
    """
    try:
        N = int(input_str.strip())
    except:
        return ""

    if N <= 0:
        return "0\n"

    # Digital root d(x) maps to 1..9: x%9 if != 0 else 9
    # Count numbers in [1,N] by residue class (1..9)
    counts = [0] * 10
    rem = N % 9
    full = N // 9

    for i in range(1, 10):
        counts[i] = full
        if i <= rem:
            counts[i] += 1

    # total: all (A,B,C) with d(AB)=d(C) using residue math
    total = 0
    for i in range(1, 10):
        for j in range(1, 10):
            prod = (i * j) % 9
            if prod == 0:
                prod = 9
            total += counts[i] * counts[j] * counts[prod]

    # Subtract exact products A*B=C where C <= N
    exact = 0
    for C in range(1, N + 1):
        s = int(C**0.5)
        for A in range(1, s + 1):
            if C % A == 0:
                B = C // A
                if B <= N:
                    exact += 1

    return str(max(0, total - exact)) + "\n"
